import{_ as l}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as s,D as f,o as t,c,I as p,w as d,k as o,a as h,R as k,b as u,e as _}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const I=JSON.parse('{"title":"Kafka","description":"从消息模型到 Java 客户端、Spring Kafka、可靠性与集群的顺序学习路线。","frontmatter":{"title":"Kafka","date":"2026-11-05T00:00:00.000Z","category":"Java课程","tags":["Java","Kafka","消息队列"],"description":"从消息模型到 Java 客户端、Spring Kafka、可靠性与集群的顺序学习路线。"},"headers":[],"relativePath":"courses/java/16-Kafka/index.md","filePath":"courses/java/16-Kafka/index.md","lastUpdated":1793885095000}'),m={name:"courses/java/16-Kafka/index.md"},K=o("h1",{id:"kafka",tabindex:"-1"},[h("Kafka "),o("a",{class:"header-anchor",href:"#kafka","aria-label":'Permalink to "Kafka"'},"​")],-1),g=k('<p>Kafka 是分布式事件流平台。学习时先问三个问题：<strong>谁写入事件？事件按什么顺序存储？谁从哪个位置读取？</strong> 这分别对应 Producer（生产者）、Topic 分区日志和 Consumer（消费者）的 offset（位移）。</p><h2 id="为什么按这个顺序学" tabindex="-1">为什么按这个顺序学 <a class="header-anchor" href="#为什么按这个顺序学" aria-label="Permalink to &quot;为什么按这个顺序学&quot;">​</a></h2><p>先用命令行发一条消息，能看见原始行为；再写 Java 客户端，才知道 API 映射到哪一步。理解分区与 offset 后，再学消费组、ACK、复制和故障恢复。直接从 Spring 注解入手，容易把自动提交、重试和重复消费混在一起。</p><p>打个比方：如果你开一家快递站，得先搞清楚&quot;谁寄包裹&quot;&quot;包裹按什么顺序放在货架上&quot;&quot;谁取包裹&quot;，再去研究怎么批量收件、怎么保证不丢件。Kafka 的学习也是同样的逻辑。</p><h2 id="学完应能做什么" tabindex="-1">学完应能做什么 <a class="header-anchor" href="#学完应能做什么" aria-label="Permalink to &quot;学完应能做什么&quot;">​</a></h2><ul><li>画出 Producer → Broker 分区 → Consumer Group 的完整数据流。</li><li>用 Java 创建 Topic、发送消息、读取消息和处理失败。</li><li>解释&quot;至少一次&quot;为什么会重复，以及业务如何做幂等。</li><li>区分四个阶段：消息已到 Broker、已被复制、已被消费、业务已完成。</li><li>规划分区数、副本数和消费组实例数的关系。</li><li>判断什么时候该用 Kafka，什么时候不该用。</li></ul><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p>按下面顺序读。先理解消息为什么要异步传递，再动手创建 Topic，最后学习可靠性与集群。</p><ol><li><a href="./02-消息队列与MQ核心知识">消息队列与 MQ 核心知识</a>：理解异步、解耦与不同交付语义。</li><li><a href="./03-Kafka快速入门与安装">Kafka 快速入门与安装</a>：搭建 KRaft 单节点并收发消息。</li><li><a href="./04-命令行生产消费与消息模型">命令行生产消费与消息模型</a>：用命令验证 Topic、分区、偏移量。</li><li><a href="./05-Spring-Boot集成与Admin-API">Spring Boot 集成与 Admin API</a>：配置连接、创建和查看 Topic。</li><li><a href="./06-Producer-API与发送实践">Producer API 与发送实践</a>：学习发送、回调、幂等和分区。</li><li><a href="./07-Consumer-API与消费实践">Consumer API 与消费实践</a>：学习轮询、消费组、位移和再均衡。</li><li><a href="./08-存储复制与可靠性">存储、复制与可靠性</a>：理解日志、ISR、ACK 和水位。</li><li><a href="./09-高可用与性能">高可用、性能与总结选型</a>：规划集群、故障恢复、吞吐，回顾边界并决定什么时候使用 Kafka。</li><li><a href="./10-Spring-Kafka项目整合">Spring Kafka 项目整合</a>：将发送与监听接入服务。</li></ol><p>图片课程中的 Spring Boot 2.x 和 ZooKeeper 作为历史背景；这里的实践统一采用 JDK 20、Spring Boot 3 和 KRaft。Kafka 4.0 已移除 ZooKeeper 模式，见 <a href="https://kafka.apache.org/40/getting-started/upgrade/" target="_blank" rel="noreferrer">Apache Kafka 升级说明</a>。</p><p>示例默认使用本机 <code>localhost:9092</code> 和实验 Topic；业务环境应配置认证、权限、超时与监控。<a href="https://kafka.apache.org/documentation/" target="_blank" rel="noreferrer">Kafka 官方文档</a>和<a href="https://docs.spring.io/spring-kafka/reference/" target="_blank" rel="noreferrer">Spring Kafka 文档</a>是后续速查入口。</p>',11);function P(a,A,S,q,T,C){const i=l,n=f("ClientOnly");return t(),c("div",null,[K,p(n,null,{default:d(()=>{var e,r;return[(((e=a.$frontmatter)==null?void 0:e.aside)??!0)&&(((r=a.$frontmatter)==null?void 0:r.showArticleMetadata)??!0)?(t(),u(i,{key:0,article:a.$frontmatter},null,8,["article"])):_("",!0)]}),_:1}),g])}const B=s(m,[["render",P]]);export{I as __pageData,B as default};
